package com.lexora.service.core.database

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

@Entity(tableName = "organizations") data class OrganizationEntity(@PrimaryKey val id: String, val name: String, val isActive: Boolean, val updatedAtEpochMs: Long)
@Entity(tableName = "clients", indices = [Index("organizationId"), Index(value = ["organizationId", "phone"])]) data class ClientEntity(@PrimaryKey val id: String, val organizationId: String, val type: String, val displayName: String, val phone: String?, val email: String?, val taxId: String?, val kpp: String?, val registrationAddress: String?, val actualAddress: String?, val note: String?, val consentPersonalData: Boolean, val archived: Boolean, val syncState: String, val createdAtEpochMs: Long, val updatedAtEpochMs: Long)
@Entity(tableName = "vehicles", indices = [Index("organizationId"), Index("clientId"), Index(value = ["organizationId", "registrationNumber"])]) data class VehicleEntity(@PrimaryKey val id: String, val organizationId: String, val clientId: String?, val registrationNumber: String, val vin: String?, val make: String?, val model: String?, val year: Int?, val bodyType: String?, val color: String?, val mileageKm: Int?, val archived: Boolean, val syncState: String, val createdAtEpochMs: Long, val updatedAtEpochMs: Long)
@Entity(tableName = "branches", indices = [Index("organizationId")]) data class BranchEntity(@PrimaryKey val id: String, val organizationId: String, val name: String, val address: String?, val phone: String?, val email: String?, val workSchedule: String?, val timeZoneId: String, val active: Boolean, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "employees", indices = [Index("organizationId"), Index("branchId")]) data class EmployeeEntity(@PrimaryKey val id: String, val organizationId: String, val branchId: String?, val displayName: String, val position: String?, val phone: String?, val email: String?, val active: Boolean, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "module_settings", primaryKeys = ["organizationId", "moduleId"]) data class ModuleSettingEntity(val organizationId: String, val moduleId: String, val enabled: Boolean, val licenseStatus: String, val updatedAtEpochMs: Long)
@Entity(tableName = "audit_events", indices = [Index("organizationId"), Index("entityId"), Index("occurredAtEpochMs")]) data class AuditEventEntity(@PrimaryKey val id: String, val organizationId: String, val userId: String, val entityType: String, val entityId: String?, val action: String, val summary: String, val occurredAtEpochMs: Long)
@Entity(tableName = "service_history", indices = [Index("organizationId"), Index("vehicleId"), Index("occurredAtEpochMs")]) data class ServiceHistoryEntity(@PrimaryKey val id: String, val organizationId: String, val vehicleId: String, val sourceType: String, val sourceId: String?, val title: String, val description: String?, val mileageKm: Int?, val occurredAtEpochMs: Long, val createdAtEpochMs: Long)
@Entity(tableName = "service_objects", indices = [Index("organizationId"), Index("clientId")]) data class ServiceObjectEntity(@PrimaryKey val id: String, val organizationId: String, val clientId: String?, val name: String, val address: String?, val accessMode: String?, val responsibleContact: String?, val archived: Boolean, val syncState: String, val createdAtEpochMs: Long, val updatedAtEpochMs: Long)
@Entity(tableName = "equipment", indices = [Index("organizationId"), Index("serviceObjectId"), Index(value = ["organizationId", "serialNumber"])]) data class EquipmentEntity(@PrimaryKey val id: String, val organizationId: String, val serviceObjectId: String?, val type: String, val make: String?, val model: String?, val serialNumber: String?, val inventoryNumber: String?, val barcode: String?, val commissionedNote: String?, val warrantyNote: String?, val archived: Boolean, val syncState: String, val createdAtEpochMs: Long, val updatedAtEpochMs: Long)
@Entity(tableName = "service_requests", indices = [Index("organizationId"), Index("clientId"), Index("branchId"), Index("assigneeEmployeeId"), Index("status"), Index(value = ["organizationId", "number"], unique = true)]) data class ServiceRequestEntity(@PrimaryKey val id: String, val organizationId: String, val number: String, val clientId: String?, val vehicleId: String?, val serviceObjectId: String?, val equipmentId: String?, val branchId: String?, val assigneeEmployeeId: String?, val title: String, val description: String?, val status: String, val priority: String, val plannedAtEpochMs: Long?, val dueAtEpochMs: Long?, val slaDeadlineEpochMs: Long?, val closedAtEpochMs: Long?, val archived: Boolean, val syncState: String, val createdAtEpochMs: Long, val updatedAtEpochMs: Long)
@Entity(tableName = "request_status_history", indices = [Index("requestId"), Index("changedAtEpochMs")]) data class RequestStatusHistoryEntity(@PrimaryKey val id: String, val requestId: String, val fromStatus: String?, val toStatus: String, val changedByUserId: String, val changedAtEpochMs: Long, val comment: String?)
@Entity(tableName = "service_visits", indices = [Index("organizationId"), Index("requestId"), Index("employeeId"), Index("status")]) data class ServiceVisitEntity(@PrimaryKey val id: String, val organizationId: String, val requestId: String, val branchId: String?, val employeeId: String?, val status: String, val plannedStartEpochMs: Long?, val plannedEndEpochMs: Long?, val actualStartEpochMs: Long?, val actualEndEpochMs: Long?, val resultNote: String?, val customerName: String?, val customerSignatureRef: String?, val syncState: String, val createdAtEpochMs: Long, val updatedAtEpochMs: Long)
@Entity(tableName = "visit_checklist_items", indices = [Index("visitId"), Index("sortOrder")]) data class VisitChecklistItemEntity(@PrimaryKey val id: String, val visitId: String, val title: String, val state: String, val comment: String?, val sortOrder: Int, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "visit_work_entries", indices = [Index("visitId")]) data class VisitWorkEntryEntity(@PrimaryKey val id: String, val visitId: String, val serviceCode: String?, val title: String, val quantity: Double, val unit: String?, val note: String?, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "visit_material_usage", indices = [Index("visitId")]) data class VisitMaterialUsageEntity(@PrimaryKey val id: String, val visitId: String, val materialCode: String?, val title: String, val quantity: Double, val unit: String?, val note: String?, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "visit_photos", indices = [Index("visitId"), Index("takenAtEpochMs")]) data class VisitPhotoEntity(@PrimaryKey val id: String, val visitId: String, val localUri: String, val caption: String?, val takenAtEpochMs: Long, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "service_documents", indices = [Index("organizationId"), Index("requestId"), Index("visitId"), Index("clientId"), Index("type"), Index(value = ["organizationId", "number"], unique = true)]) data class ServiceDocumentEntity(@PrimaryKey val id: String, val organizationId: String, val requestId: String?, val visitId: String?, val clientId: String?, val type: String, val number: String, val status: String, val issuedAtEpochMs: Long?, val totalMinor: Long, val currency: String, val externalFileRef: String?, val note: String?, val archived: Boolean, val syncState: String, val createdAtEpochMs: Long, val updatedAtEpochMs: Long)
@Entity(tableName = "payments", indices = [Index("organizationId"), Index("requestId"), Index("documentId"), Index("clientId"), Index("status")]) data class PaymentEntity(@PrimaryKey val id: String, val organizationId: String, val requestId: String?, val documentId: String?, val clientId: String?, val amountMinor: Long, val currency: String, val status: String, val method: String, val paidAtEpochMs: Long?, val externalReference: String?, val note: String?, val archived: Boolean, val syncState: String, val createdAtEpochMs: Long, val updatedAtEpochMs: Long)
@Entity(tableName = "sync_operations", indices = [Index("organizationId"), Index("entityType"), Index("entityId"), Index("status"), Index("nextAttemptAtEpochMs"), Index(value = ["organizationId", "idempotencyKey"], unique = true)]) data class SyncOperationEntity(@PrimaryKey val id: String, val organizationId: String, val entityType: String, val entityId: String, val operationType: String, val idempotencyKey: String, val payloadJson: String?, val status: String, val attemptCount: Int, val nextAttemptAtEpochMs: Long?, val lastError: String?, val createdAtEpochMs: Long, val updatedAtEpochMs: Long)
@Entity(tableName = "sync_conflicts", indices = [Index("organizationId"), Index("entityType"), Index("entityId"), Index("resolution"), Index("detectedAtEpochMs")]) data class SyncConflictEntity(@PrimaryKey val id: String, val organizationId: String, val entityType: String, val entityId: String, val localVersionJson: String?, val remoteVersionJson: String?, val resolution: String, val detectedAtEpochMs: Long, val resolvedAtEpochMs: Long?)
@Entity(tableName = "wash_posts", indices = [Index("organizationId"), Index("branchId"), Index("status")]) data class WashPostEntity(@PrimaryKey val id: String, val organizationId: String, val branchId: String?, val name: String, val status: String, val active: Boolean, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "wash_queue", indices = [Index("organizationId"), Index("requestId"), Index("vehicleId"), Index("postId"), Index("status"), Index("position")]) data class WashQueueItemEntity(@PrimaryKey val id: String, val organizationId: String, val requestId: String?, val vehicleId: String?, val postId: String?, val position: Int, val status: String, val createdAtEpochMs: Long, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "wash_tech_cards", indices = [Index("organizationId"), Index("active")]) data class WashTechCardEntity(@PrimaryKey val id: String, val organizationId: String, val name: String, val durationMinutes: Int, val stepsText: String, val active: Boolean, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "wash_chemical_usage", indices = [Index("organizationId"), Index("requestId"), Index("postId"), Index("usedAtEpochMs")]) data class WashChemicalUsageEntity(@PrimaryKey val id: String, val organizationId: String, val requestId: String?, val postId: String?, val chemicalName: String, val quantityMl: Double, val usedAtEpochMs: Long, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "tire_queue", indices = [Index("organizationId"), Index("requestId"), Index("vehicleId"), Index("status"), Index("position")]) data class TireQueueItemEntity(@PrimaryKey val id: String, val organizationId: String, val requestId: String?, val vehicleId: String?, val position: Int, val status: String, val createdAtEpochMs: Long, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "tire_diagnostics", indices = [Index("organizationId"), Index("requestId"), Index("vehicleId"), Index("diagnosedAtEpochMs")]) data class TireDiagnosticEntity(@PrimaryKey val id: String, val organizationId: String, val requestId: String?, val vehicleId: String?, val pressureNote: String?, val treadDepthMm: Double?, val damageNote: String?, val recommendation: String?, val diagnosedAtEpochMs: Long, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "tire_work_entries", indices = [Index("organizationId"), Index("requestId"), Index("vehicleId"), Index("performedAtEpochMs")]) data class TireWorkEntryEntity(@PrimaryKey val id: String, val organizationId: String, val requestId: String?, val vehicleId: String?, val title: String, val quantity: Double, val note: String?, val performedAtEpochMs: Long, val syncState: String, val updatedAtEpochMs: Long)
@Entity(tableName = "tire_storage", indices = [Index("organizationId"), Index("clientId"), Index("vehicleId"), Index("status"), Index(value = ["organizationId", "storageCode"], unique = true)]) data class TireStorageItemEntity(@PrimaryKey val id: String, val organizationId: String, val clientId: String?, val vehicleId: String?, val storageCode: String, val tireDescription: String, val quantity: Int, val location: String?, val status: String, val storedAtEpochMs: Long, val issuedAtEpochMs: Long?, val syncState: String, val updatedAtEpochMs: Long)
